/**
 * @summary Get chronological signal feed for all assets
 */
export const getGetSignalFeedUrl = (params?: GetSignalFeedParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/signals/feed?${stringifiedParams}`
    : `/api/signals/feed`;
};

export const getSignalFeed = async (
  params?: GetSignalFeedParams,
  options?: RequestInit,
): Promise<SignalFeedEntry[]> => {
  return customFetch<SignalFeedEntry[]>(getGetSignalFeedUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getGetSignalFeedQueryKey = (params?: GetSignalFeedParams) => {
  return [`/api/signals/feed`, ...(params ? [params] : [])] as const;
};

export const getGetSignalFeedQueryOptions = <
  TData = Awaited<ReturnType<typeof getSignalFeed>>,
  TError = ErrorType<unknown>,
>(
  params?: GetSignalFeedParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getSignalFeed>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getGetSignalFeedQueryKey(params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof getSignalFeed>>> = ({
    signal,
  }) => getSignalFeed(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof getSignalFeed>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type GetSignalFeedQueryResult = NonNullable<
  Awaited<ReturnType<typeof getSignalFeed>>
>;
export type GetSignalFeedQueryError = ErrorType<unknown>;

/**
 * @summary Get chronological signal feed for all assets
 */

export function useGetSignalFeed<
  TData = Awaited<ReturnType<typeof getSignalFeed>>,
  TError = ErrorType<unknown>,
>(
  params?: GetSignalFeedParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getSignalFeed>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getGetSignalFeedQueryOptions(params, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}

